(()=>{var BASE_URL=location.origin+"/";document.querySelector("head base").href=BASE_URL;document.getElementById("date").innerHTML=`&copy; ${new Date().getFullYear()} - Pokedex. <span class="d-none d-md-inline">Todos os direitos reservados.</span>`;var modal=document.getElementById("modal"),modalBody=document.getElementById("modal-body"),modalCloseBtn=document.getElementById("modal-close-btn"),modalClose=()=>modal.close(),modalOpen=(msg=null,type="text-dark")=>{msg&&(modalBody.innerHTML=msg),type&&modal.classList.add(type),modal.showModal()};modal.onclose=e=>{["text-primary","text-info","text-secondary","text-dark","text-danger","text-warning","text-success","splash"].map(e2=>modal.classList.remove(e2)),modalBody.innerHTML=null};modalCloseBtn.onclick=modalClose;var setupInteractions=()=>{document.querySelector("body")?.addEventListener("click",e=>{let btn=e.target.closest("[data-action]");if(!btn)return;let{action}=btn.dataset,file=btn.href.split("#")[1];if(action==="content"&&(location.hash="#"+file,getPage(file+".html",action,file.charAt(0).toUpperCase()+file.slice(1))),action==="modal"&&getModal(file+".html"),action==="detail"){e.preventDefault();let url=btn.dataset.url;getDetailPage(url)}})};var getData=async url=>{try{let resp=await fetch(url);if(!resp.ok)throw new Error(`HTTP error! status: ${resp.status}`);return resp.json()}catch(error){throw console.error("Error fetching data:",error),error}},getText=async url=>{try{let page=await fetch(BASE_URL+url);if(!page.ok)throw new Error(`HTTP error! status: ${page.status}`);return page.text()}catch(error){throw console.error("Error fetching text:",error),error}},getModal=async url=>{try{let data=await getText(url);modalOpen(data)}catch(error){console.error("Error fetching modal content:",error)}},getPage=async(url,id,title="Template Base")=>{document.getElementById(id).innerHTML='<div class="spinner">loading</div>',document.title=title;try{let data=await getText(url);document.getElementById(id).innerHTML=data,setupInteractions()}catch{document.getElementById(id).innerHTML="<p>Error loading content.</p>"}},getDetailPage=async url=>{try{let data=await getData(url),response=await fetch(BASE_URL+"detail.html");if(!response.ok)throw new Error(`HTTP error! status: ${response.status}`);let detailPageContent=await response.text(),doc=new DOMParser().parseFromString(detailPageContent,"text/html");return doc.getElementById("pokemon-name").textContent=data.name,doc.getElementById("pokemon-id").textContent=`#${data.id}`,doc.getElementById("pokemon-img").src=data.sprites.other.dream_world.front_default,doc.getElementById("pokemon-experience").textContent=data.base_experience,doc.getElementById("pokemon-height").textContent=data.height,doc.getElementById("pokemon-weight").textContent=data.weight,doc.getElementById("pokemon-order").textContent=data.order,modalOpen(doc.documentElement.outerHTML)}catch(error){throw console.error("Error fetching detail page content:",error),error}};var pokedex={api:"https://pokeapi.co/api/v2/pokemon/",offset:0,limit:10,getPokemons:async function(){return(await(await fetch(`${this.api}?offset=${this.offset}&limit=${this.limit}`)).json()).results},getPokemonDetails:async function(url){return await(await fetch(url)).json()},getMorePokemons:async function(){return this.offset+=this.limit,(await(await fetch(`${this.api}?offset=${this.offset}&limit=${this.limit}`)).json()).results},renderPokemons:async function(pokemons){pokemons.forEach(async pokemon=>{let details=await pokedex.getPokemonDetails(pokemon.url),card=document.createElement("div");card.classList.add("card"),card.innerHTML=`<div class="card-body d-flex flex-column justify-content-between"><h1 class="card-title fw-light fs-3">${details.name} <small class="fs-6 float-end">#${details.id}</small></h1><img src="${details.sprites.other.dream_world.front_default}" alt="${details.name}" class="card-img-top my-2" /><div class="p-1 d-flex justify-content-between align-items-center"><section id="badges">${details.abilities.map(ability=>`<span class="badge bg-purple text-purple">${ability.ability.name}</span>`).join(" ")}</section><nav><a data-action="detail" data-url="${pokemon.url}" href="#detail" class="btn btn-sm btn-yellow">Detail</a></nav></div></div>`,document.querySelector(".grid").appendChild(card)})}};pokedex.getPokemons().then(pokemons=>{pokedex.renderPokemons(pokemons)}).then(()=>{let getMore=document.getElementById("getMore");getMore.onclick=e=>{e.preventDefault(),pokedex.getMorePokemons().then(pokemons=>{pokedex.renderPokemons(pokemons)})}});if(location.hash==="")getPage("home.html","content","Home");else throw new Error("Eita!!! A rota n\xE3o existe");})();
